"use client";

import { motion } from "motion/react";

export function SlideFillButtonTailwind({ label = "Get started" }) {
  return (
    <motion.button
      type="button"
      initial="rest"
      animate="rest"
      whileHover="active"
      whileFocus="active"
      className="relative overflow-hidden rounded-lg border border-zinc-700 bg-zinc-900 px-5 py-2.5 text-sm font-medium text-zinc-100 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-[3px] focus-visible:outline-zinc-200"
    >
      <motion.span
        aria-hidden
        className="absolute inset-0 bg-zinc-100"
        variants={{ rest: { x: "-101%" }, active: { x: 0 } }}
        transition={{ duration: 0.35, ease: [0.22, 1, 0.36, 1] }}
      />
      <motion.span className="relative" variants={{ rest: { color: "#f4f4f5" }, active: { color: "#09090b" } }}>
        {label}
      </motion.span>
    </motion.button>
  );
}
